CREATE TABLE t_guard (id BIGINT NOT NULL COMMENT 'id',sk BIGINT NOT NULL COMMENT 'sk',u INT NOT NULL COMMENT 'u',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'created',update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'updated',is_deleted TINYINT NOT NULL DEFAULT 0 COMMENT 'deleted',PRIMARY KEY(id,sk),CONSTRAINT uk_u UNIQUE(u)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='plain' shardkey=sk /* CREATE VIEW */;